shell_commands:
cat > patch_acceptance.ts << 'EOF'
import {readFileSync, writeFileSync} from 'fs';

const filePath = 'src/orchestration/tools/registry.acceptance.test.ts';
let content = readFileSync(filePath, 'utf-8');

const targetStr = `        if (round === 2) {
          const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
          firstRoundToolResult = lastMessage.content[0]?.content ?? '';
          yield {
            type: 'tool_use',
            toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
          };
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        yield {type: 'text', text: '22C in Paris'};
        yield {type: 'stop', stopReason: 'end_turn'};`;

const replacementStr = `        if (round !== 2) {
          yield {type: 'text', text: '22C in Paris'};
          yield {type: 'stop', stopReason: 'end_turn'};
          return;
        }
        const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
        const [firstContent] = lastMessage.content;
        firstRoundToolResult = firstContent?.content ?? '';
        yield {
          type: 'tool_use',
          toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
        };
        yield {type: 'stop', stopReason: 'tool_use'};`;

if (content.includes(targetStr)) {
  content = content.replace(targetStr, replacementStr);
  writeFileSync(filePath, content, 'utf-8');
  console.log("Replaced successfully!");
} else {
  console.log("Target string not found!");
}
EOF
node patch_acceptance.ts

